#include "viofs.h"
#ifdef HOST
#include <string.h>
#else
void *memcpy(void*,const void*,size_t); void *memset(void*,int,size_t); size_t strlen(const char*); int strcmp(const char*,const char*); int strncmp(const char*,const char*,size_t);
int memcmp(const void*,const void*,size_t);
#endif
/* Absturzsicherheit durch Schreibreihenfolge: erst Bitmap und Daten, dann Inode, zuletzt der
   Ordnereintrag. Stromausfall kann Bloecke verlieren, aber nie Daten verfaelschen. */
typedef uint32_t u32; typedef uint64_t u64; typedef uint8_t u8;
#define BS 4096
#define PB (BS/4)
#define NDIR 12
#define DE 256
typedef struct { char magic[8]; u32 ver,blocks,bmap_start,bmap_n,ino_start,ino_n,data_start,ninodes; } super;
typedef struct { u32 type,mtime; u64 size; u32 d[NDIR]; u32 ind,dind; u8 pad[56]; } inode;
typedef char inode_size_check[sizeof(inode)==128?1:-1];
typedef struct { u32 ino; u8 type,len; char name[VFS_NAME]; } dirent;
typedef char dirent_size_check[sizeof(dirent)==256?1:-1];
enum { T_FREE,T_FILE,T_DIR };
#define NC 64
static struct { u32 b; int ok; u8 d[BS]; } cache[NC];
static vfs_dev dev; static super sb; static int mounted; static u64 freeblk; static u32 hint=1,ihint=2;
static int rawr(u32 b,void*p){ for(int i=0;i<8;i++) if(dev.rd(dev.start+(u64)b*8+i,(u8*)p+i*512))return VE_IO; return 0; }
static int raww(u32 b,const void*p){ for(int i=0;i<8;i++) if(dev.wr(dev.start+(u64)b*8+i,(const u8*)p+i*512))return VE_IO; return 0; }
static u8 *bget(u32 b){ int s=b%NC; if(cache[s].ok&&cache[s].b==b)return cache[s].d; if(rawr(b,cache[s].d)){ cache[s].ok=0; return 0; } cache[s].b=b; cache[s].ok=1; return cache[s].d; }
static int bput(u32 b,const void*p){ int s=b%NC; if(raww(b,p)){ cache[s].ok=0; return VE_IO; } if(p!=cache[s].d)memcpy(cache[s].d,p,BS); cache[s].b=b; cache[s].ok=1; return 0; }
static void cache_clear(void){ for(int i=0;i<NC;i++)cache[i].ok=0; }
static int bit(u32 b){ u8*p=bget(sb.bmap_start+b/(BS*8)); if(!p)return -1; return p[(b%(BS*8))/8]>>(b%8)&1; }
static int setbit(u32 b,int v){ u32 m=sb.bmap_start+b/(BS*8); u8*p=bget(m); if(!p)return VE_IO; u8 mask=1<<(b%8); u32 o=(b%(BS*8))/8; if(v)p[o]|=mask; else p[o]&=~mask; return bput(m,p); }
static u32 balloc(void){ if(!freeblk)return 0; for(u32 n=0;n<sb.blocks;n++){ u32 b=hint+n; if(b>=sb.blocks)b-=sb.blocks-sb.data_start; if(b<sb.data_start)continue; int v=bit(b); if(v<0)return 0; if(!v){ if(setbit(b,1))return 0; freeblk--; hint=b+1; if(hint>=sb.blocks)hint=sb.data_start; return b; } } return 0; }
static void bfree(u32 b){ if(b<sb.data_start||b>=sb.blocks)return; if(!setbit(b,0))freeblk++; }
static int iget(u32 n,inode*o){ if(!n||n>=sb.ninodes)return VE_IO; u8*p=bget(sb.ino_start+n/(BS/128)); if(!p)return VE_IO; memcpy(o,p+(n%(BS/128))*128,128); return 0; }
static int iput(u32 n,const inode*i){ u32 b=sb.ino_start+n/(BS/128); u8*p=bget(b); if(!p)return VE_IO; memcpy(p+(n%(BS/128))*128,i,128); return bput(b,p); }
static u32 ialloc(void){ for(u32 k=0;k<sb.ninodes;k++){ u32 n=ihint+k; if(n>=sb.ninodes)n=2+(n-sb.ninodes); if(n<2)continue; inode i; if(iget(n,&i))return 0; if(i.type==T_FREE){ ihint=n+1; if(ihint>=sb.ninodes)ihint=2; return n; } } return 0; }
/* Blocknummer zu Dateiposition; bei create werden fehlende Bloecke angelegt */
static u32 ptr(u32*slot,int*dirty,int create){ if(*slot)return *slot; if(!create)return 0; u32 b=balloc(); if(!b)return 0; static u8 z[BS]; memset(z,0,BS); if(bput(b,z)){ bfree(b); return 0; } *slot=b; *dirty=1; return b; }
static u32 bmap(inode*i,u64 idx,int create){ if(idx<NDIR){ if(!i->d[idx]&&create){ u32 b=balloc(); if(!b)return 0; i->d[idx]=b; } return i->d[idx]; } idx-=NDIR; int dirty=0; u32 ib;
  if(idx<PB)ib=ptr(&i->ind,&dirty,create); else { idx-=PB; if(idx>=(u64)PB*PB)return 0; u32 db=ptr(&i->dind,&dirty,create); if(!db)return 0; u8*p=bget(db); if(!p)return 0; u32 *t=(u32*)p,e=t[idx/PB]; if(!e&&create){ e=ptr(&e,&dirty,1); if(!e)return 0; p=bget(db); if(!p)return 0; ((u32*)p)[idx/PB]=e; if(bput(db,p))return 0; } ib=e; idx%=PB; }
  if(!ib)return 0; u8*p=bget(ib); if(!p)return 0; u32 b=((u32*)p)[idx]; if(!b&&create){ b=balloc(); if(!b)return 0; p=bget(ib); if(!p)return 0; ((u32*)p)[idx]=b; if(bput(ib,p))return 0; } return b; }
static void ifree(inode*i){ static u32 t1[PB],t2[PB]; for(int k=0;k<NDIR;k++)bfree(i->d[k]); if(i->ind){ u8*p=bget(i->ind); if(p){ memcpy(t1,p,BS); for(u32 k=0;k<PB;k++)bfree(t1[k]); } bfree(i->ind); } if(i->dind){ u8*p=bget(i->dind); if(p){ memcpy(t2,p,BS); for(u32 j=0;j<PB;j++){ if(!t2[j])continue; u8*q=bget(t2[j]); if(q){ memcpy(t1,q,BS); for(u32 k=0;k<PB;k++)bfree(t1[k]); } bfree(t2[j]); } } bfree(i->dind); } }
static int namelen(const char*s,const char*e){ return (int)(e-s); }
/* Ordnereintrag suchen; liefert Inode, optional Block und Slot */
static int dfind(inode*dir,const char*n,int l,u32*ino,u8*type,u32*bo,int*sl){ u64 cnt=dir->size/BS; for(u64 k=0;k<cnt;k++){ u32 b=bmap(dir,k,0); if(!b)continue; u8*p=bget(b); if(!p)return VE_IO; for(int s=0;s<BS/DE;s++){ dirent*d=(dirent*)(p+s*DE); if(d->ino&&d->len==l&&!strncmp(d->name,n,l)){ *ino=d->ino; if(type)*type=d->type; if(bo)*bo=b; if(sl)*sl=s; return 0; } } } return VE_NOENT; }
static int lookup(const char*path,u32*ino){ if(path[0]!='/')return VE_INVAL; u32 cur=1; const char*p=path; while(*p){ while(*p=='/')p++; if(!*p)break; const char*e=p; while(*e&&*e!='/')e++; inode d; if(iget(cur,&d))return VE_IO; if(d.type!=T_DIR)return VE_NOTDIR; u32 n; int r=dfind(&d,p,namelen(p,e),&n,0,0,0); if(r)return r; cur=n; p=e; } *ino=cur; return 0; }
/* Trennt Pfad in Elternordner und letzten Namen */
static int split(const char*path,u32*parent,const char**name,int*nl){ size_t l=strlen(path); if(l<2||path[0]!='/'||l>=VFS_PATH)return VE_INVAL; const char*e=path+l; while(e>path+1&&e[-1]=='/')e--; const char*s=e; while(s>path&&s[-1]!='/')s--; int n=(int)(e-s); if(n<=0||n>VFS_NAME)return VE_INVAL; if((n==1&&s[0]=='.')||(n==2&&s[0]=='.'&&s[1]=='.'))return VE_INVAL; for(int i=0;i<n;i++) if(s[i]=='/'||(u8)s[i]<32)return VE_INVAL; *name=s;*nl=n; char par[VFS_PATH]; size_t pl=s-path; if(pl>=VFS_PATH)return VE_INVAL; memcpy(par,path,pl); par[pl]=0; int r=lookup(par,parent); if(r)return r; inode d; if(iget(*parent,&d))return VE_IO; return d.type==T_DIR?0:VE_NOTDIR; }
static int dadd(u32 pn,inode*dir,const char*n,int l,u32 ino,u8 type,u32 now){ u64 cnt=dir->size/BS; for(u64 k=0;k<cnt;k++){ u32 b=bmap(dir,k,0); if(!b)continue; u8*p=bget(b); if(!p)return VE_IO; for(int s=0;s<BS/DE;s++){ dirent*d=(dirent*)(p+s*DE); if(!d->ino){ memset(d,0,DE); memcpy(d->name,n,l); d->type=type; d->len=(u8)l; d->ino=ino; int r=bput(b,p); if(r)return r; dir->mtime=now; return iput(pn,dir); } } }
  u32 b=bmap(dir,cnt,1); if(!b)return VE_NOSPC; static u8 z[BS]; memset(z,0,BS); dirent*d=(dirent*)z; memcpy(d->name,n,l); d->type=type; d->len=(u8)l; d->ino=ino; int r=bput(b,z); if(r)return r; dir->size=(cnt+1)*BS; dir->mtime=now; return iput(pn,dir); }
static int dclear(u32 b,int sl){ u8*p=bget(b); if(!p)return VE_IO; memset(p+sl*DE,0,DE); return bput(b,p); }
static void countfree(void){ freeblk=0; for(u32 b=sb.data_start;b<sb.blocks;b++) if(bit(b)==0)freeblk++; }
int vfs_mkdir(const char*path,u32 now);
int vfs_format(const vfs_dev*d,u32 now){ dev=*d; cache_clear(); mounted=0; u64 blocks=d->sectors/8; if(blocks<256)return VE_NOSPC; if(blocks>0xFFFFFFF0ull)blocks=0xFFFFFFF0ull; u64 ni=blocks/8; if(ni<64)ni=64; if(ni>65536)ni=65536; memset(&sb,0,sizeof sb); memcpy(sb.magic,"VIOFS2\0\0",8); sb.ver=2; sb.blocks=(u32)blocks; sb.bmap_start=1; sb.bmap_n=(u32)((blocks+BS*8-1)/(BS*8)); sb.ino_start=1+sb.bmap_n; sb.ninodes=(u32)ni; sb.ino_n=(u32)((ni*128+BS-1)/BS); sb.data_start=sb.ino_start+sb.ino_n; if(sb.data_start+16>=sb.blocks)return VE_NOSPC;
  static u8 z[BS]; memset(z,0,BS); for(u32 i=0;i<sb.bmap_n+sb.ino_n;i++) if(raww(1+i,z))return VE_IO; for(u32 b=0;b<sb.data_start;b++){ u32 m=1+b/(BS*8); u8*p=bget(m); if(!p)return VE_IO; p[(b%(BS*8))/8]|=1<<(b%8); if(b%(BS*8)==BS*8-1||b==sb.data_start-1){ if(bput(m,p))return VE_IO; } } freeblk=sb.blocks-sb.data_start; hint=sb.data_start; ihint=2; inode r; memset(&r,0,sizeof r); r.type=T_DIR; r.mtime=now; if(iput(1,&r))return VE_IO; memset(z,0,BS); memcpy(z,&sb,sizeof sb); if(raww(0,z))return VE_IO; d->fl(); mounted=1; return 0; }
int vfs_mount(const vfs_dev*d){ dev=*d; cache_clear(); mounted=0; static u8 b[BS]; if(rawr(0,b))return VE_IO; memcpy(&sb,b,sizeof sb); if(memcmp(sb.magic,"VIOFS2\0\0",8)||sb.ver!=2||sb.blocks>d->sectors/8||sb.data_start>=sb.blocks||sb.ninodes<3||sb.bmap_start!=1||sb.ino_start!=1+sb.bmap_n||(u64)sb.ninodes*128>(u64)sb.ino_n*BS||sb.data_start<sb.ino_start+sb.ino_n||(u64)sb.bmap_n*BS*8<sb.blocks)return VE_INVAL; hint=sb.data_start; ihint=2; countfree(); mounted=1; return 0; }
void vfs_unmount(void){ mounted=0; cache_clear(); }
int vfs_mounted(void){ return mounted; }
int vfs_stat(const char*path,vfs_ent*e){ if(!mounted)return VE_IO; u32 n; int r=lookup(path,&n); if(r)return r; inode i; if(iget(n,&i))return VE_IO; if(e){ e->dir=i.type==T_DIR; e->size=i.size; e->mtime=i.mtime; const char*s=path; for(const char*p=path;*p;p++) if(*p=='/'&&p[1])s=p+1; size_t l=strlen(s); if(l>VFS_NAME)l=VFS_NAME; memcpy(e->name,s,l); e->name[l]=0; } return 0; }
int64_t vfs_read(const char*path,void*buf,u64 max){ if(!mounted)return VE_IO; u32 n; int r=lookup(path,&n); if(r)return r; inode i; if(iget(n,&i))return VE_IO; if(i.type==T_DIR)return VE_ISDIR; u64 sz=i.size<max?i.size:max,o=0; while(o<sz){ u32 b=bmap(&i,o/BS,0); u64 c=sz-o>BS?BS:sz-o; if(!b)memset((u8*)buf+o,0,c); else { u8*p=bget(b); if(!p)return VE_IO; memcpy((u8*)buf+o,p,c); } o+=c; } return (int64_t)sz; }
int vfs_write(const char*path,const void*buf,u64 len,u32 now){ if(!mounted)return VE_IO; if(len>(u64)(NDIR+PB+(u64)PB*PB)*BS)return VE_NOSPC; u32 pn; const char*nm; int nl; int r=split(path,&pn,&nm,&nl); if(r)return r; inode dir; if(iget(pn,&dir))return VE_IO; u32 old=0; r=dfind(&dir,nm,nl,&old,0,0,0); if(r&&r!=VE_NOENT)return r; inode oi; int ex=!r; if(ex){ if(iget(old,&oi))return VE_IO; if(oi.type==T_DIR)return VE_ISDIR; }
  if((len/BS+1)*102/100+4>freeblk)return VE_NOSPC; inode ni; memset(&ni,0,sizeof ni); ni.type=T_FILE; ni.mtime=now; ni.size=len; static u8 t[BS]; u64 o=0; while(o<len){ u32 b=bmap(&ni,o/BS,1); if(!b){ ifree(&ni); return VE_NOSPC; } u64 c=len-o>BS?BS:len-o; memset(t,0,BS); memcpy(t,(const u8*)buf+o,c); if(raww(b,t)){ ifree(&ni); return VE_IO; } int s=b%NC; if(cache[s].b==b)cache[s].ok=0; o+=c; } dev.fl();
  u32 n=old; if(!ex){ n=ialloc(); if(!n){ ifree(&ni); return VE_NOSPC; } } if(iput(n,&ni)){ ifree(&ni); return VE_IO; } dev.fl(); if(ex)ifree(&oi); else { r=dadd(pn,&dir,nm,nl,n,T_FILE,now); if(r){ ni.type=T_FREE; iput(n,&ni); ifree(&ni); return r; } } dev.fl(); return 0; }
int vfs_mkdir(const char*path,u32 now){ if(!mounted)return VE_IO; u32 pn; const char*nm; int nl; int r=split(path,&pn,&nm,&nl); if(r)return r; inode dir; if(iget(pn,&dir))return VE_IO; u32 x; if(!dfind(&dir,nm,nl,&x,0,0,0))return VE_EXIST; u32 n=ialloc(); if(!n)return VE_NOSPC; inode i; memset(&i,0,sizeof i); i.type=T_DIR; i.mtime=now; if(iput(n,&i))return VE_IO; r=dadd(pn,&dir,nm,nl,n,T_DIR,now); if(r){ i.type=T_FREE; iput(n,&i); return r; } dev.fl(); return 0; }
static int empty(inode*d){ u64 c=d->size/BS; for(u64 k=0;k<c;k++){ u32 b=bmap(d,k,0); if(!b)continue; u8*p=bget(b); if(!p)return 0; for(int s=0;s<BS/DE;s++) if(((dirent*)(p+s*DE))->ino)return 0; } return 1; }
int vfs_remove(const char*path){ if(!mounted)return VE_IO; u32 pn; const char*nm; int nl; int r=split(path,&pn,&nm,&nl); if(r)return r; inode dir; if(iget(pn,&dir))return VE_IO; u32 n,bo; int sl; r=dfind(&dir,nm,nl,&n,0,&bo,&sl); if(r)return r; inode i; if(iget(n,&i))return VE_IO; if(i.type==T_DIR&&!empty(&i))return VE_NOTEMPTY; if(dclear(bo,sl))return VE_IO; dev.fl(); inode f=i; f.type=T_FREE; if(iput(n,&f))return VE_IO; ifree(&i); dev.fl(); return 0; }
int vfs_rename(const char*from,const char*to){ if(!mounted)return VE_IO; u32 sp,dp; const char*sn,*dn; int sl,dl; int r=split(from,&sp,&sn,&sl); if(r)return r; r=split(to,&dp,&dn,&dl); if(r)return r; size_t fl=strlen(from); if(!strncmp(to,from,fl)&&(to[fl]=='/'||!to[fl]))return VE_INVAL; inode sd,dd; if(iget(sp,&sd)||iget(dp,&dd))return VE_IO; u32 n,bo,x; u8 ty; int slot; r=dfind(&sd,sn,sl,&n,&ty,&bo,&slot); if(r)return r; if(!dfind(&dd,dn,dl,&x,0,0,0))return VE_EXIST; r=dadd(dp,&dd,dn,dl,n,ty,sd.mtime); if(r)return r; if(iget(sp,&sd))return VE_IO; r=dfind(&sd,sn,sl,&n,&ty,&bo,&slot); if(r)return r; if(dclear(bo,slot))return VE_IO; dev.fl(); return 0; }
int vfs_list(const char*path,int(*cb)(const vfs_ent*,void*),void*arg){ if(!mounted)return VE_IO; u32 n; int r=lookup(path,&n); if(r)return r; inode d; if(iget(n,&d))return VE_IO; if(d.type!=T_DIR)return VE_NOTDIR; u64 c=d.size/BS; static vfs_ent e; static u8 blk[BS]; for(u64 k=0;k<c;k++){ u32 b=bmap(&d,k,0); if(!b)continue; u8*p=bget(b); if(!p)return VE_IO; memcpy(blk,p,BS); for(int s=0;s<BS/DE;s++){ dirent*x=(dirent*)(blk+s*DE); if(!x->ino||x->len>VFS_NAME)continue; memcpy(e.name,x->name,x->len); e.name[x->len]=0; e.dir=x->type==T_DIR; inode i; if(iget(x->ino,&i))return VE_IO; e.size=i.size; e.mtime=i.mtime; if(cb(&e,arg))return 0; } } return 0; }
void vfs_usage(u64*t,u64*f,u32*files){ if(!mounted){ *t=*f=0; if(files)*files=0; return; } *t=(u64)(sb.blocks-sb.data_start)*BS; *f=freeblk*BS; if(files){ u32 c=0; for(u32 n=2;n<sb.ninodes;n++){ inode i; if(!iget(n,&i)&&i.type==T_FILE)c++; } *files=c; } }
int vfs_norm(const char*cwd,const char*in,char*o,size_t n){ char t[VFS_PATH*2]; size_t m=0; if(in[0]!='/'){ size_t l=strlen(cwd); if(l>=VFS_PATH)return VE_INVAL; memcpy(t,cwd,l); m=l; t[m++]='/'; } size_t il=strlen(in); if(il>=VFS_PATH||m+il+1>=sizeof t)return VE_INVAL; memcpy(t+m,in,il+1); size_t w=0; if(n<2)return VE_INVAL; o[w++]='/'; const char*p=t; while(*p){ while(*p=='/')p++; if(!*p)break; const char*e=p; while(*e&&*e!='/')e++; size_t l=e-p; if(l==1&&p[0]=='.'){ p=e; continue; } if(l==2&&p[0]=='.'&&p[1]=='.'){ if(w>1){ w--; while(w>1&&o[w-1]!='/')w--; } p=e; continue; } if(w+l+2>=n||w+l+2>=VFS_PATH)return VE_INVAL; memcpy(o+w,p,l); w+=l; o[w++]='/'; p=e; } if(w>1)w--; o[w]=0; return 0; }
const char *vfs_errstr(int e,int en){ switch(e){ case VE_NOENT:return en?"Not found":"Nicht gefunden"; case VE_EXIST:return en?"Already exists":"Existiert bereits"; case VE_NOSPC:return en?"Disk full":"Datenträger voll"; case VE_NOTDIR:return en?"Not a folder":"Kein Ordner"; case VE_NOTEMPTY:return en?"Folder is not empty":"Ordner ist nicht leer"; case VE_INVAL:return en?"Invalid name":"Ungültiger Name"; case VE_ISDIR:return en?"Is a folder":"Ist ein Ordner"; case VE_DENIED:return en?"Access not allowed":"Zugriff nicht erlaubt"; case VE_NOFS:return en?"No writable storage here":"Hier kein beschreibbarer Datenträger"; case VE_FORMAT:return en?"Format not supported":"Format nicht unterstützt"; default:return en?"Disk error":"Datenträgerfehler"; } }
